using Godot;
using Godot.Collections;

public partial class FamilyTreePanel : Control
{
    private const float CardW=120,CardH=56,HGap=40,VGap=80; private Control? container; private readonly List<Node> rendered=[];
    public override void _Ready(){AddToGroup("map_overlay_blocker");Hide();container=GetNodeOrNull<Control>("%TreeContainer");if(GetNodeOrNull<Button>("%CloseBtn") is { } close)close.Pressed+=Hide;}
    public Rect2 get_ui_rect()=>GetNodeOrNull<Panel>("Panel")?.GetGlobalRect()??GetGlobalRect();
    public void refresh(){clear();if(container is null)return;var registry=GetNodeOrNull<EntityRegistry>("/root/EntityRegistry");var members=registry?.get_entities_of_type((int)WorldEntity.EntityType.CHARACTER).Where(member=>member.Get("is_family").AsBool()).OrderBy(member=>member.Get("family_gen").AsInt32()).ThenBy(member=>member.Get("entity_name").AsString()).ToList()??[];if(members.Count==0){container.AddChild(new Label{Text="（暂无家族成员，请先通过婚姻生育建立家族）",Position=new(80,120)});Show();return;}var groups=members.GroupBy(member=>member.Get("family_gen").AsInt32()).OrderBy(group=>group.Key).ToArray();var max=groups.Max(group=>group.Count());for(var gi=0;gi<groups.Length;gi++){var group=groups[gi].ToArray();var width=group.Length*CardW+(group.Length-1)*HGap;var start=(max*(CardW+HGap)-HGap-width)*.5f+60;var y=60+gi*(CardH+VGap);container.AddChild(new Label{Text=$"第{groups[gi].Key}代",Position=new(5,y+20)});for(var i=0;i<group.Length;i++){var center=new Vector2(start+i*(CardW+HGap)+CardW*.5f,y+CardH*.5f);if(gi>0){var prev=groups[gi-1].Count();var from=new Vector2((max*(CardW+HGap)-HGap)*.5f+60,60+(gi-1)*(CardH+VGap)+CardH);add_line(from,new(center.X,y));}add_card(group[i],new(start+i*(CardW+HGap),y));}}Show();}
    private void clear(){foreach(var node in rendered)node.QueueFree();rendered.Clear();if(container is not null)foreach(var child in container.GetChildren())child.QueueFree();}
    private void add_line(Vector2 from,Vector2 to){if(container is null)return;var line=new Line2D{DefaultColor=new(.9f,.82f,.55f),Width=2.5f,ZIndex=-1};line.AddPoint(from);line.AddPoint(to);container.AddChild(line);rendered.Add(line);}
    private void add_card(GodotObject member,Vector2 position){if(container is null)return;var card=new Panel{Position=position,Size=new(CardW,CardH),MouseFilter=MouseFilterEnum.Stop};var style=new StyleBoxFlat{BgColor=new(.2f,.16f,.1f,.92f),BorderColor=new(.75f,.65f,.4f,.8f),BorderWidthLeft=1,BorderWidthTop=1,BorderWidthRight=1,BorderWidthBottom=1};card.AddThemeStyleboxOverride("panel",style);card.AddChild(new Label{Text=member.Get("entity_name").AsString(),Position=new(0,5),Size=new(CardW,22),HorizontalAlignment=HorizontalAlignment.Center});card.AddChild(new Label{Text=$"({member.Get("family_gender").AsString()})  {member.Get("current_age").AsInt32()}岁",Position=new(0,30),Size=new(CardW,18),HorizontalAlignment=HorizontalAlignment.Center});card.GuiInput+=input=>{if(input is InputEventMouseButton {Pressed:true,ButtonIndex:MouseButton.Left,DoubleClick:true})foreach(var panel in GetTree().GetNodesInGroup("human_info_panel"))if(panel.HasMethod("show_entity")){Hide();panel.Call("show_entity",member);break;}};container.AddChild(card);rendered.Add(card);}
}
